#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<int> adj(n, 0);
    for (int i = 0; i < m; i++) {
        adj[edges[i][0] - 1] |= 1 << (edges[i][1] - 1);
        adj[edges[i][1] - 1] |= 1 << (edges[i][0] - 1);
    }
    vector<vector<char>> ext(1 << n, vector<char>(n, 0));
    for (int mask = 1; mask < (1 << n); mask++) {
        for (int v = 0; v < n; v++) {
            if (!((mask >> v) & 1)) continue;
            int rest = mask ^ (1 << v);
            if (rest == 0) {
                ext[mask][v] = 1;
            } else {
                for (int u = 0; u < n; u++) {
                    if (((adj[v] >> u) & 1) && ((rest >> u) & 1) && ext[rest][u]) {
                        ext[mask][v] = 1;
                        break;
                    }
                }
            }
        }
    }
    int full = (1 << n) - 1;
    vector<int> path;
    for (int s = 0; s < n && path.empty(); s++) {
        if (!ext[full][s]) continue;
        path.push_back(s);
        int mask = full ^ (1 << s), v = s;
        while (mask) {
            for (int u = 0; u < n; u++) {
                if (((adj[v] >> u) & 1) && ((mask >> u) & 1) && ext[mask][u]) {
                    path.push_back(u);
                    mask ^= 1 << u;
                    v = u;
                    break;
                }
            }
        }
    }
    if (path.empty()) {
        cout << -1 << "\n";
    } else {
        for (size_t i = 0; i < path.size(); i++) cout << (i ? " " : "") << path[i] + 1;
        cout << "\n";
    }

    return 0;
}

